# Locates (approximately) the mode of logf by bracketing a sign change in
# its derivative and bisecting. This avoids optimize()'s instability when
# the density underflows to exact 0 far from the mode (e.g. dnorm at
# |x| > ~40), which can make a naive optimize() over a wide range return a
# point anywhere in that numerically-flat region.
.find_mode <- function(logf, grad_fn, lower, upper, x_hint,
                        max_attempts = 100) {
  x0 <- .nudge_into_support(logf, x_hint, x_hint)
  g0 <- grad_fn(x0)
  if (abs(g0) < 1e-8) return(x0)
  dir <- if (g0 > 0) 1 else -1
  bound <- if (dir > 0) upper else lower

  step <- max(abs(x0), 1)
  x_prev <- x0; g_prev <- g0
  x_cur <- x0
  for (i in seq_len(max_attempts)) {
    x_cur <- x_prev + dir * step
    if ((dir > 0 && x_cur >= bound) || (dir < 0 && x_cur <= bound)) {
      x_cur <- bound - dir * 1e-6 * max(1, abs(bound))
      return(.nudge_into_support(logf, x_cur, x0))
    }
    g_cur <- grad_fn(x_cur)
    if (sign(g_cur) != sign(g_prev) || g_cur == 0) break
    x_prev <- x_cur; g_prev <- g_cur
    step <- step * 1.6
  }
  if (sign(g_cur) == sign(g_prev) && g_cur != 0) {
    stop("Could not locate the mode of the log-density; it may not be a ",
         "proper (integrable) log-concave density on the given domain.")
  }

  lo <- min(x_prev, x_cur); hi <- max(x_prev, x_cur)
  for (i in 1:60) {
    xm <- (lo + hi) / 2
    gm <- grad_fn(xm)
    if (gm > 0) lo <- xm else hi <- xm
    if (abs(gm) < 1e-8) break
  }
  (lo + hi) / 2
}

